package ama.transcript;
import ama.contract.MinutesContracts.*;import java.util.*;import org.junit.jupiter.api.Test;import static ama.contract.MinutesContracts.*;import static org.junit.jupiter.api.Assertions.*;
class MinutesMaterialSourceTest {
 static String id(int n){return MinutesEditSourcesTest.id(n);}static final String H="a".repeat(64);
 FullRow locator(String kind,Long page,Long paragraph,String section){return new FullRow(Table.SOURCE_LOCATOR,List.of(cell(id(1)),cell(id(2)),cell(kind),new NullCell(),new NullCell(),kind.equals("KNOWLEDGE_VERSION")?new NullCell():cell(id(6)),kind.equals("KNOWLEDGE_VERSION")?cell(id(3)):new NullCell(),page==null?new NullCell():cell(page),paragraph==null?new NullCell():cell(paragraph),section==null?new NullCell():cell(section),new NullCell(),new NullCell()));}
 FullRow unit(long n,Long page,Long paragraph,String section,String body){return new FullRow(Table.PARSED_UNIT,List.of(cell(id(4)),cell(n),cell(page==null?"PARAGRAPH":"PAGE"),page==null?new NullCell():cell(page),paragraph==null?new NullCell():cell(paragraph),section==null?new NullCell():cell(section),cell(body)));}
 List<FullRow> rows(FullRow...units){var rows=new ArrayList<FullRow>();rows.add(new FullRow(Table.PARSED_DOCUMENT,List.of(cell(id(4)),cell(id(3)),cell("parser.v1"),cell(id(5)),cell(units.length))));rows.addAll(List.of(units));return rows;}
 SourceVersion file(){return new FileVersion(id(6),id(3),id(4),"parser.v1",H);}
 @Test void exactPageAndParagraphReturnTheirOwnTextAndVersionedFile(){var rows=rows(unit(1,1L,null,null,"第一页"),unit(2,2L,null,null,"第二页"));var source=MinutesMaterialSource.read(rows,locator("PDF_PAGE",2L,null,null),file());assertEquals("第二页",source.text());assertEquals(id(6),source.fileId());var paragraphs=rows(unit(1,null,1L,"甲","甲正文"),unit(2,null,1L,"乙","乙正文"));assertEquals("乙正文",MinutesMaterialSource.read(paragraphs,locator("WORD_PARAGRAPH",null,1L,"乙"),file()).text());}
 @Test void knowledgeVersionUsesItsPinnedContentAndCompleteParsedUnits(){var rows=rows(unit(1,null,1L,null,"第一段"),unit(2,null,2L,null,"第二段"));var source=MinutesMaterialSource.read(rows,locator("KNOWLEDGE_VERSION",null,null,null),new KnowledgeVersion(id(3),"provider","document","v1",id(6),id(4),"parser.v1",H));assertEquals("第一段\n\n第二段",source.text());assertEquals(id(3),source.materialRevisionId());}
 @Test void wrongPageParserAndVersionCannotReadAnotherSource(){var rows=rows(unit(1,1L,null,null,"正文"));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows,locator("PDF_PAGE",2L,null,null),file()));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows,locator("PDF_PAGE",1L,null,null),new FileVersion(id(6),id(3),id(4),"parser.v2",H)));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows,locator("KNOWLEDGE_VERSION",null,null,null),file()));}
 @Test void knowledgePhysicalParagraphUsesItsDerivedVersionAndExactFile(){var source=MinutesMaterialSource.read(rows(unit(1,null,1L,"制度","知识库段落")),locator("TEXT_PARAGRAPH",null,1L,"制度"),new KnowledgeVersion(id(3),"provider","document","v1",id(6),id(4),"parser.v1",H));assertEquals("知识库段落",source.text());assertEquals(id(3),source.materialRevisionId());assertEquals(id(6),source.fileId());}
 @Test void physicalLocationRejectsAnotherFileEvenWhenParsedRevisionMatches(){var rows=rows(unit(1,1L,null,null,"正文"));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows,locator("PDF_PAGE",1L,null,null),new FileVersion(id(99),id(3),id(4),"parser.v1",H)));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows,locator("PDF_PAGE",1L,null,null),new KnowledgeVersion(id(3),"provider","document","v1",id(99),id(4),"parser.v1",H)));}
 @Test void physicalLocatorCannotSmuggleAnUnrelatedMaterialRevision(){var original=locator("PDF_PAGE",1L,null,null);var cells=new ArrayList<>(original.cells());cells.set(Table.SOURCE_LOCATOR.index("material_revision_id"),cell(id(3)));assertThrows(Failure.class,()->MinutesMaterialSource.read(rows(unit(1,1L,null,null,"正文")),new FullRow(Table.SOURCE_LOCATOR,cells),file()));}

}
